<?php
declare(strict_types=1);

require_once __DIR__.'/../lib/safety_vote_work_items.php';

function svwi_campaign(int$id,bool$lock=false):?array{return db_row('SELECT c.id,c.CampaignCode,c.Status,c.IsHidden,c.IsTest,c.CurrentVersionID,v.CampaignType,v.WorkSource FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=?'.($lock?' FOR UPDATE':''),[$id]);}
function svwi_gallery(int$ownerId):array{$rows=db_rows("SELECT g.id,g.FileID fileId,g.AltText altText,g.Caption caption,g.SortOrder sortOrder,g.IsCover isCover,f.MimeType mimeType,f.FileSize fileSize FROM SafetyVote_GalleryItems g JOIN SafetyVote_Files f ON f.id=g.FileID AND f.Status='Active' WHERE g.OwnerType='candidate' AND g.OwnerID=? AND g.Status='Active' ORDER BY g.IsCover DESC,g.SortOrder,g.id",[$ownerId]);foreach($rows as&$row){$row['id']=(int)$row['id'];$row['fileId']=(int)$row['fileId'];$row['sortOrder']=(int)$row['sortOrder'];$row['isCover']=(bool)$row['isCover'];}unset($row);return$rows;}
function svwi_rows(int$versionId):array{$rows=db_rows("SELECT id,CandidateNo,DisplayName,ProfileText,SourceType,SourceCampaignID,SourceCandidateID,SortOrder FROM SafetyVote_Candidates WHERE CampaignVersionID=? AND Status IN ('Active','Finalist') ORDER BY SortOrder,id",[$versionId]);$out=[];foreach($rows as$row){$ownerId=$row['SourceType']==='imported'&&!empty($row['SourceCandidateID'])?(int)$row['SourceCandidateID']:(int)$row['id'];$out[]=['id'=>(int)$row['id'],'workCode'=>$row['CandidateNo'],'title'=>$row['DisplayName'],'description'=>$row['ProfileText']?:'','sourceType'=>$row['SourceType'],'sourceCampaignId'=>$row['SourceCampaignID']?(int)$row['SourceCampaignID']:null,'sourceCandidateId'=>$row['SourceCandidateID']?(int)$row['SourceCandidateID']:null,'sortOrder'=>(int)$row['SortOrder'],'gallery'=>svwi_gallery($ownerId)];}return$out;}
function svwi_abort(string$code,int$status):void{throw new RuntimeException($code.'|'.$status);}
function svwi_store_uploaded_file(array$file,string$scopeType):array{if((int)($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||(int)($file['size']??0)>10*1024*1024)json_response(['success'=>false,'code'=>'MEDIA_FILE_REJECTED','message'=>'A JPG, PNG or WebP image not exceeding 10 MB is required.'],400);$mime=sv_file_mime((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'code'=>'MEDIA_FILE_REJECTED','message'=>'Image signature is invalid.'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=sv_private_dir().DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'code'=>'MEDIA_FILE_REJECTED','message'=>'Unable to store image.'],500);return['stored'=>$stored,'target'=>$target,'mime'=>$mime,'size'=>(int)$file['size'],'name'=>svwi_text($file['name']??'',255),'sha256'=>hash_file('sha256',$target),'scopeType'=>$scopeType];}

function handle_safety_vote_work_item_routes(string$method,string$path):bool{
    $adminWorks=route_params($path,'/safety-vote/admin/campaigns/:id/works');
    $publicWorks=route_params($path,'/safety-vote/campaigns/:id/works');
