    if($adminWorks&&$method==='GET'){
        sv_require_permission($user,'SAFETY_VOTE_MANAGE');$campaign=svwi_campaign((int)$adminWorks['id']);
        if(!$campaign)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);
        if($campaign['CampaignType']!=='jury_scoring')json_response(['success'=>false,'code'=>'WORKFLOW_PROFILE_CONFLICT'],409);
        json_response(['success'=>true,'data'=>['campaignId'=>(int)$campaign['id'],'workSource'=>$campaign['WorkSource']?:'admin_curated','rows'=>svwi_rows((int)$campaign['CurrentVersionID']),'contractVersion'=>SV_WORK_ITEMS_CONTRACT]]);
    }
    if($publicWorks&&$method==='GET'){
        $campaign=svwi_campaign((int)$publicWorks['id']);
        if(!$campaign||$campaign['CampaignType']!=='jury_scoring'||(int)$campaign['IsHidden']===1||(int)$campaign['IsTest']===1||!in_array($campaign['Status'],['Scheduled','Open','Closed','Certified','Published'],true))json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);
        json_response(['success'=>true,'data'=>['campaignId'=>(int)$campaign['id'],'readOnly'=>true,'publicGallery'=>true,'rows'=>svwi_rows((int)$campaign['CurrentVersionID']),'contractVersion'=>SV_WORK_ITEMS_CONTRACT]]);
    }
    if($adminWorks&&$method==='PUT'){
        sv_require_permission($user,'SAFETY_VOTE_MANAGE');$parsed=svwi_parse(json_body());if(!$parsed['ok'])json_response(['success'=>false,'code'=>'WORK_ITEMS_INVALID','details'=>$parsed['errors']],400);
        $pdo=db();$pdo->beginTransaction();try{$campaign=svwi_campaign((int)$adminWorks['id'],true);if(!$campaign)throw new RuntimeException('CAMPAIGN_NOT_FOUND');if($campaign['Status']!=='Draft'||$campaign['CampaignType']!=='jury_scoring')json_response(['success'=>false,'code'=>'WORKFLOW_STATE_CONFLICT'],409);$works=$parsed['works'];
            if($parsed['source']==='employee_submission'){$works=[];foreach(db_rows("SELECT id,SubmissionCode,Title,Description FROM SafetyVote_Submissions WHERE CampaignID=? AND CampaignVersionID=? AND Status IN ('Accepted','Finalist') ORDER BY id",[$campaign['id'],$campaign['CurrentVersionID']])as$index=>$item)$works[]=['id'=>null,'workCode'=>$item['SubmissionCode']?:('SUB-'.$item['id']),'title'=>$item['Title'],'description'=>$item['Description']?:null,'sourceCandidateId'=>null,'submissionId'=>(int)$item['id'],'sortOrder'=>$index+1];}
            if($parsed['source']==='imported'){$sourceIds=array_values(array_unique(array_map(static function($item){return(int)$item['sourceCandidateId'];},$works)));$marks=implode(',',array_fill(0,count($sourceIds),'?'));$sources=$sourceIds?db_rows("SELECT sc.id,sc.CandidateNo,sc.DisplayName,sc.ProfileText,sv.CampaignID FROM SafetyVote_Candidates sc JOIN SafetyVote_CampaignVersions sv ON sv.id=sc.CampaignVersionID JOIN SafetyVote_Campaigns s ON s.id=sv.CampaignID WHERE sc.id IN ($marks) AND sc.Status IN ('Active','Finalist') AND s.Status IN ('Scheduled','Open','Closed','Certified','Published') AND s.IsHidden=0 AND s.IsTest=0",$sourceIds):[];$map=[];foreach($sources as$source)$map[(int)$source['id']]=$source;if(count($map)!==count($sourceIds))json_response(['success'=>false,'code'=>'SOURCE_WORK_UNAVAILABLE'],409);foreach($works as&$item){$source=$map[(int)$item['sourceCandidateId']];if($item['title']==='')$item['title']=$source['DisplayName'];if(!$item['description'])$item['description']=$source['ProfileText']?:null;$item['sourceCampaignId']=(int)$source['CampaignID'];}unset($item);}
            $current=db_rows("SELECT id FROM SafetyVote_Candidates WHERE CampaignVersionID=? AND Status IN ('Active','Finalist') FOR UPDATE",[$campaign['CurrentVersionID']]);$currentIds=array_map('intval',array_column($current,'id'));$keep=[];
            foreach($works as$item){$candidateId=$item['id']&&in_array((int)$item['id'],$currentIds,true)?(int)$item['id']:null;if($candidateId){db_execute("UPDATE SafetyVote_Candidates SET OptionID=NULL,SubmissionID=?,CandidateNo=?,DisplayName=?,ProfileText=?,SourceType=?,SourceCampaignID=?,SourceCandidateID=?,SortOrder=?,Status='Active',UpdatedBy=? WHERE id=? AND CampaignVersionID=?",[$item['submissionId']??null,$item['workCode'],$item['title'],$item['description'],$parsed['source'],$item['sourceCampaignId']??null,$item['sourceCandidateId'],$item['sortOrder'],sv_actor($user),$candidateId,$campaign['CurrentVersionID']]);}else{db_execute("INSERT INTO SafetyVote_Candidates(CampaignVersionID,OptionID,SubmissionID,CandidateNo,SourceType,SourceCampaignID,SourceCandidateID,DisplayName,ProfileText,Status,SortOrder,CreatedBy,UpdatedBy) VALUES(?,NULL,?,?,?,?,?,?,?,'Active',?,?,?)",[$campaign['CurrentVersionID'],$item['submissionId']??null,$item['workCode'],$parsed['source'],$item['sourceCampaignId']??null,$item['sourceCandidateId'],$item['title'],$item['description'],$item['sortOrder'],sv_actor($user),sv_actor($user)]);$candidateId=(int)$pdo->lastInsertId();}$keep[]=$candidateId;}
            if($keep){$marks=implode(',',array_fill(0,count($keep),'?'));db_execute("UPDATE SafetyVote_Candidates SET Status='Inactive',UpdatedBy=? WHERE CampaignVersionID=? AND Status IN ('Active','Finalist') AND id NOT IN ($marks)",array_merge([sv_actor($user),$campaign['CurrentVersionID']],$keep));}else db_execute("UPDATE SafetyVote_Candidates SET Status='Inactive',UpdatedBy=? WHERE CampaignVersionID=? AND Status IN ('Active','Finalist')",[sv_actor($user),$campaign['CurrentVersionID']]);
            db_execute('UPDATE SafetyVote_CampaignVersions SET WorkSource=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[$parsed['source'],sv_actor($user),$campaign['CurrentVersionID']]);sv_audit($user,'SAFETY_VOTE_WORK_ITEMS_SAVE','SafetyVote_CampaignVersion',(string)$campaign['CurrentVersionID'],'source='.$parsed['source'].'; works='.count($keep),['workSource'=>$parsed['source'],'workCount'=>count($keep)],(int)$campaign['id'],(int)$campaign['CurrentVersionID']);$pdo->commit();json_response(['success'=>true,'data'=>['campaignId'=>(int)$campaign['id'],'workSource'=>$parsed['source'],'rows'=>svwi_rows((int)$campaign['CurrentVersionID']),'serverConfirmed'=>true,'contractVersion'=>SV_WORK_ITEMS_CONTRACT]]);
        }catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>$error->getMessage()==='CAMPAIGN_NOT_FOUND'?'CAMPAIGN_NOT_FOUND':'WORK_ITEMS_SAVE_FAILED'],500);}
    }
