            if($scopeType==='question_image'){$entity=db_row('SELECT id,ImageFileID FROM SafetyVote_Questions WHERE id=? AND CampaignVersionID=? FOR UPDATE',[$scopeId,$campaign['CurrentVersionID']]);$prior=$entity&&!empty($entity['ImageFileID'])?(int)$entity['ImageFileID']:null;}
            elseif($scopeType==='option_image'){$entity=db_row('SELECT o.id,o.FileID FROM SafetyVote_Options o JOIN SafetyVote_Questions q ON q.id=o.QuestionID WHERE o.id=? AND q.CampaignVersionID=? FOR UPDATE',[$scopeId,$campaign['CurrentVersionID']]);$prior=$entity&&!empty($entity['FileID'])?(int)$entity['FileID']:null;}
            else{$entity=db_row("SELECT id FROM SafetyVote_Candidates WHERE id=? AND CampaignVersionID=? AND Status IN ('Active','Finalist') FOR UPDATE",[$scopeId,$campaign['CurrentVersionID']]);$count=db_row("SELECT COUNT(*) total FROM SafetyVote_GalleryItems WHERE OwnerType='candidate' AND OwnerID=? AND Status='Active' FOR UPDATE",[$scopeId]);if($scopeType==='work_cover'){$cover=db_row("SELECT id,FileID FROM SafetyVote_GalleryItems WHERE OwnerType='candidate' AND OwnerID=? AND Status='Active' AND IsCover=1 LIMIT 1 FOR UPDATE",[$scopeId]);$prior=$cover?(int)$cover['FileID']:null;}}
            if(!$entity)svwi_abort('MEDIA_TARGET_NOT_FOUND',404);if(isset($count)&&(int)$count['total']>=12&&($scopeType!=='work_cover'||empty($cover)))svwi_abort('GALLERY_LIMIT_REACHED',409);db_execute('INSERT INTO SafetyVote_Files(CampaignID,CampaignVersionID,FilePurpose,StoredName,OriginalName,MimeType,FileSize,ContentSha256,UploadedBy) VALUES(?,?,?,?,?,?,?,?,?)',[$campaign['id'],$campaign['CurrentVersionID'],$scopeType,$stored['stored'],$stored['name'],$stored['mime'],$stored['size'],$stored['sha256'],sv_actor($user)]);$fileId=(int)$pdo->lastInsertId();
            if($scopeType==='question_image')db_execute('UPDATE SafetyVote_Questions SET ImageFileID=?,ImageAltText=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[$fileId,$alt,sv_actor($user),$scopeId]);elseif($scopeType==='option_image')db_execute('UPDATE SafetyVote_Options SET FileID=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[$fileId,sv_actor($user),$scopeId]);else{if($scopeType==='work_cover')db_execute("UPDATE SafetyVote_GalleryItems SET IsCover=0,Status=IF(IsCover=1,'Removed',Status),UpdatedBy=?,RowVersion=RowVersion+1 WHERE OwnerType='candidate' AND OwnerID=? AND Status='Active' AND IsCover=1",[sv_actor($user),$scopeId]);$order=db_row("SELECT COALESCE(MAX(SortOrder),0)+1 nextOrder FROM SafetyVote_GalleryItems WHERE OwnerType='candidate' AND OwnerID=? AND Status='Active'",[$scopeId]);db_execute("INSERT INTO SafetyVote_GalleryItems(CampaignID,CampaignVersionID,OwnerType,OwnerID,FileID,AltText,Caption,SortOrder,IsCover,CreatedBy,UpdatedBy) VALUES(?,?,'candidate',?,?,?,?,?,?,?,?)",[$campaign['id'],$campaign['CurrentVersionID'],$scopeId,$fileId,$alt,$caption?:null,(int)$order['nextOrder'],$scopeType==='work_cover'?1:0,sv_actor($user),sv_actor($user)]);}if($prior)db_execute("UPDATE SafetyVote_Files SET Status='Removed',RemovedBy=?,RemovedAt=NOW(),RemovalReason='Atomic media replacement' WHERE id=? AND Status='Active'",[sv_actor($user),$prior]);db_execute('INSERT INTO SafetyVote_MediaMutations(CampaignID,CampaignVersionID,ScopeType,ScopeID,Action,FileID,PriorFileID,RequestKey,PayloadSha256,ActorEmployeeID) VALUES(?,?,?,?,?,?,?,?,?,?)',[$campaign['id'],$campaign['CurrentVersionID'],$scopeType,$scopeId,$prior?'replace':'upload',$fileId,$prior,$key,$payloadHash,sv_actor($user)]);sv_audit($user,$prior?'SAFETY_VOTE_MEDIA_REPLACE':'SAFETY_VOTE_MEDIA_UPLOAD','SafetyVote_File',(string)$fileId,$scopeType.':'.$scopeId,['priorFileId'=>$prior,'sha256'=>$stored['sha256']],(int)$campaign['id'],(int)$campaign['CurrentVersionID']);$pdo->commit();json_response(['success'=>true,'data'=>['fileId'=>$fileId,'priorFileId'=>$prior,'scopeType'=>$scopeType,'scopeId'=>$scopeId,'sha256'=>$stored['sha256'],'serverConfirmed'=>true,'replayed'=>false]],201);
        }catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();@unlink($stored['target']);$parts=explode('|',$error->getMessage(),2);$known=count($parts)===2&&ctype_digit($parts[1]);json_response(['success'=>false,'code'=>$known?$parts[0]:'ATOMIC_MEDIA_UPLOAD_FAILED'],$known?(int)$parts[1]:500);}
    }
    if($atomic&&$method==='DELETE'){
        sv_require_permission($user,'SAFETY_VOTE_MANAGE');$body=json_body();$scopeType=(string)($body['scopeType']??'');$scopeId=svwi_id($body['scopeId']??null);$reason=svwi_text($body['reason']??'',500);$key=svwi_text($_SERVER['HTTP_IDEMPOTENCY_KEY']??'',100);if(!$scopeId||!in_array($scopeType,['question_image','option_image','work_cover','work_gallery'],true)||mb_strlen($reason)<10||$key==='')json_response(['success'=>false,'code'=>'MEDIA_REQUEST_INVALID'],400);$hash=hash('sha256',json_encode(['scopeType'=>$scopeType,'scopeId'=>$scopeId,'reason'=>$reason]));$pdo=db();$pdo->beginTransaction();try{$campaign=svwi_campaign((int)$atomic['id'],true);if(!$campaign||$campaign['Status']!=='Draft')svwi_abort('CAMPAIGN_STATE_CONFLICT',409);$replay=db_row('SELECT PayloadSha256 FROM SafetyVote_MediaMutations WHERE CampaignID=? AND RequestKey=? FOR UPDATE',[$campaign['id'],$key]);if($replay){$pdo->rollBack();if($replay['PayloadSha256']!==$hash)json_response(['success'=>false,'code'=>'IDEMPOTENCY_CONFLICT'],409);json_response(['success'=>true,'data'=>['removed'=>true,'replayed'=>true,'serverConfirmed'=>true]]);}$fileId=null;
            if($scopeType==='question_image'){$entity=db_row('SELECT ImageFileID FROM SafetyVote_Questions WHERE id=? AND CampaignVersionID=? FOR UPDATE',[$scopeId,$campaign['CurrentVersionID']]);$fileId=$entity&&!empty($entity['ImageFileID'])?(int)$entity['ImageFileID']:null;if($entity)db_execute('UPDATE SafetyVote_Questions SET ImageFileID=NULL,ImageAltText=NULL,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[sv_actor($user),$scopeId]);}elseif($scopeType==='option_image'){$entity=db_row('SELECT o.FileID FROM SafetyVote_Options o JOIN SafetyVote_Questions q ON q.id=o.QuestionID WHERE o.id=? AND q.CampaignVersionID=? FOR UPDATE',[$scopeId,$campaign['CurrentVersionID']]);$fileId=$entity&&!empty($entity['FileID'])?(int)$entity['FileID']:null;if($entity)db_execute('UPDATE SafetyVote_Options SET FileID=NULL,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[sv_actor($user),$scopeId]);}else{$where=$scopeType==='work_cover'?' AND IsCover=1':' AND IsCover=0';$item=db_row("SELECT id,FileID FROM SafetyVote_GalleryItems WHERE OwnerType='candidate' AND OwnerID=? AND Status='Active'$where ORDER BY id DESC LIMIT 1 FOR UPDATE",[$scopeId]);$fileId=$item?(int)$item['FileID']:null;if($item)db_execute("UPDATE SafetyVote_GalleryItems SET Status='Removed',UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?",[sv_actor($user),$item['id']]);}if(!$fileId)json_response(['success'=>false,'code'=>'MEDIA_TARGET_NOT_FOUND'],404);db_execute("UPDATE SafetyVote_Files SET Status='Removed',RemovedBy=?,RemovedAt=NOW(),RemovalReason=? WHERE id=? AND Status='Active'",[sv_actor($user),$reason,$fileId]);db_execute("INSERT INTO SafetyVote_MediaMutations(CampaignID,CampaignVersionID,ScopeType,ScopeID,Action,FileID,PriorFileID,RequestKey,PayloadSha256,ActorEmployeeID) VALUES(?,?,?,?,'remove',NULL,?,?,?,?)",[$campaign['id'],$campaign['CurrentVersionID'],$scopeType,$scopeId,$fileId,$key,$hash,sv_actor($user)]);sv_audit($user,'SAFETY_VOTE_MEDIA_REMOVE','SafetyVote_File',(string)$fileId,$reason,['scopeType'=>$scopeType,'scopeId'=>$scopeId],(int)$campaign['id'],(int)$campaign['CurrentVersionID']);$pdo->commit();json_response(['success'=>true,'data'=>['fileId'=>$fileId,'removed'=>true,'replayed'=>false,'serverConfirmed'=>true]]);
        }catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();$parts=explode('|',$error->getMessage(),2);$known=count($parts)===2&&ctype_digit($parts[1]);json_response(['success'=>false,'code'=>$known?$parts[0]:'ATOMIC_MEDIA_REMOVE_FAILED'],$known?(int)$parts[1]:500);}
